def main(draft=False):
    assert not(SRC/'protocol.json').exists() and not(OUT/'preparation.json').exists();base=read(SRC.parent/'h3bt/protocol.json');pre=read(SRC/'preflight.json');assert pre['counterfactual_cost_and_exact_parity_passed'] and pre['all_inadmissible_branches_retained'] and pre['depth_normalization_parity_passed'] and pre['all4096_archived_cases_retained']
